import PlayerManager from "./player_manager";
import { PlayerAction, PlayerManagerStatus } from "./types";

const mockHowl = {
  playing: jest.fn(),
  once: jest.fn(),
  loop: jest.fn(),
  fade: jest.fn(),
  play: jest.fn(),
